package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.io.Base64Variant;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.BooleanNode;
import com.fasterxml.jackson.databind.node.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.node.POJONode;
import com.fasterxml.jackson.databind.node.TextNode;
import com.fasterxml.jackson.databind.node.utils.Base64Variants;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for TreeTraversingParser.getBinaryValue
 */
public class TreeTraversingParser_getBinaryValue_TriageGen2Test {

    private final ObjectMapper mapper = new ObjectMapper();

    @Test
    public void testGetBinaryValue_NullNode() throws IOException, JsonParseException {
        // currentNode() returns null if there is no current node
        TreeTraversingParser parser = new TreeTraversingParser(null);
        byte[] result = parser.getBinaryValue(Base64Variants.RFC4648_BASE64);
        assertNull("Should return null when currentNode is null", result);
    }

    @Test
    public void testGetBinaryValue_BinaryNode() throws IOException, JsonParseException {
        byte[] expected = new byte[]{1, 2, 3, 4};
        // Creating a node that represents binary data (via TextNode with Base64 or direct binary)
        // In Jackson, binaryValue() on a TextNode performs Base64 decoding
        String base64 = Base64Variants.RFC4648_BASE64.encode(expected);
        JsonNode node = mapper.readTree("\"" + base64 + "\"");

        // Note: To trigger n.binaryValue() returning data, we need a node that represents binary.
        // In TreeTraversingParser, the currentNode() is provided by the constructor.
        TreeTraversingParser parser = new TreeTraversingParser(node);

        byte[] result = parser.getBinaryValue(Base64Variants.RFC4648_BASE64);
        assertArrayEquals("Should return decoded binary data from TextNode", expected, result);
    }

    @Test
    public void testGetBinaryValue_TextNodeNoBinary() throws IOException, JsonParseException {
        // A TextNode that is not valid Base64 or simply returns null for binaryValue()
        // However, most TextNodes will return decoded bytes if they are valid Base64.
        // If n.binaryValue() returns null, it moves to the next check.
        // We simulate this by using a node type that doesn't support binaryValue() well or returns null.
        JsonNode node = new TextNode("not-base64-!!!"); 
        // Note: Depending on Jackson version, binaryValue on TextNode might throw or return null.
        // If it returns null, we proceed to POJO check.

        TreeTraversingParser parser = new TreeTraversingParser(node);
        byte[] result = parser.getBinaryValue(Base64Variants.RFC4648_BASE64);

        // If binaryValue() returned null and it's not a POJO, result is null
        if (result == null) {
            assertNull(result);
        }
    }

    @Test
    public void testGetBinaryValue_PojoNodeWithByteArray() throws IOException, JsonParseException {
        byte[] expected = new byte[]{10, 20, 30};
        POJONode pojoNode = new POJONode(expected);

        TreeTraversingParser parser = new TreeTraversingParser(pojoNode);
        byte[] result = parser.getBinaryValue(Base64Variants.RFC4648_BASE64);

        assertArrayEquals("Should return byte[] from POJONode", expected, result);
    }

    @Test
    public void testGetBinaryValue_PojoNodeWithNonByteArray() throws IOException, JsonParseException {
        // POJO node containing a String instead of byte[]
        POJONode pojoNode = new POJONode("not-a-byte-array");

        TreeTraversingParser parser = new TreeTraversingParser(pojoNode);
        byte[] result = parser.getBinaryValue(Base64Variants.RFC4648_BASE64);

        assertNull("Should return null if POJO is not a byte[]", result);
    }

    @Test
    public void testGetBinaryValue_OtherNodes() throws IOException, JsonParseException {
        // Test with BooleanNode to ensure it goes through all branches and returns null
        JsonNode node = BooleanNode.TRUE;
        TreeTraversingParser parser = new TreeTraversingParser(node);

        byte[] result = parser.getBinaryValue(Base64Variants.RFC4648_BASE64);
        assertNull("Should return null for BooleanNode", result);

        // Test with ArrayNode
        ArrayNode arrayNode = mapper.createArrayNode();
        arrayNode.add(1);
        TreeTraversingParser parser2 = new TreeTraversingParser(arrayNode);
        assertNull("Should return null for ArrayNode", parser2.getBinaryValue(Base64Variants.RFC4648_BASE64));
    }
}
